describe('File Upload Queue - Remove File Functionality', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully remove a file from the upload queue before submission', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-file.pdf');

    // Verify file appears in queue
    cy.get('[data-testid="upload-queue-item"]').should('be.visible');
    cy.get('[data-testid="upload-queue-item"]').should('contain', 'sample-file.pdf');

    // Verify remove button is visible
    cy.get('[data-testid="remove-file-button"]').should('be.visible');

    // Click remove button
    cy.get('[data-testid="remove-file-button"]').click();

    // Verify file is removed from queue
    cy.get('[data-testid="upload-queue-item"]').should('not.exist');

    // Verify queue is empty
    cy.get('[data-testid="upload-queue"]').should('not.contain', 'sample-file.pdf');

    // Verify remove button is no longer visible
    cy.get('[data-testid="remove-file-button"]').should('not.exist');

    // Verify submit button is enabled
    cy.get('[data-testid="submit-upload-button"]').should('not.be.disabled');

    // Submit the empty queue
    cy.get('[data-testid="submit-upload-button"]').click();

    // Verify API call is not made
    cy.wait('@fileUpload', { timeout: 1000 }).then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should handle removing the last file and display appropriate message', () => {
    // Upload two files
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document1.pdf');
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document2.pdf');

    // Verify both files are in queue
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 2);
    cy.get('[data-testid="upload-queue-item"]').first().should('contain', 'document1.pdf');
    cy.get('[data-testid="upload-queue-item"]').eq(1).should('contain', 'document2.pdf');

    // Remove the first file
    cy.get('[data-testid="upload-queue-item"]').first().find('[data-testid="remove-file-button"]').click();

    // Verify first file is removed
    cy.get('[data-testid="upload-queue-item"]').should('have.length', 1);
    cy.get('[data-testid="upload-queue-item"]').first().should('contain', 'document2.pdf');

    // Remove the last file
    cy.get('[data-testid="upload-queue-item"]').first().find('[data-testid="remove-file-button"]').click();

    // Verify queue is empty
    cy.get('[data-testid="upload-queue-item"]').should('not.exist');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-queue-message"]').should('be.visible');
    cy.get('[data-testid="empty-queue-message"]').should('contain', 'No files in upload queue');

    // Verify submit button is disabled when queue is empty
    cy.get('[data-testid="submit-upload-button"]').should('be.disabled');

    // Attempt to submit with empty queue
    cy.get('[data-testid="submit-upload-button"]').click();

    // Verify no API call is made
    cy.intercept('POST', '/api/files/upload').as('fileUpload');
    cy.wait('@fileUpload', { timeout: 1000 }).then((interception) => {
      expect(interception).to.not.exist;
    });
  });
});
